package com.jnapanam.sportszone.content.controller;import com.jnapanam.sportszone.content.dto.*;import com.jnapanam.sportszone.content.service.ContentService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/public/content")public class PublicContentController{private final ContentService service;public PublicContentController(ContentService s){service=s;}@GetMapping("/events")public List<EventResponse>events(){return service.publicEvents();}@GetMapping("/announcements")public List<AnnouncementResponse>announcements(){return service.publicAnnouncements();}@GetMapping("/gallery")public List<GalleryResponse>gallery(){return service.publicGallery();}@GetMapping("/pages/{slug}")public PageResponse page(@PathVariable String slug){return service.publicPage(slug);}@PostMapping("/contact")@ResponseStatus(HttpStatus.CREATED)public ContactResponse contact(@Valid@RequestBody ContactRequest r){return service.contact(r);}}
